  "verbo-169": {"promptNative": "Spero che lui ___ (conseguir = ottenere) il posto.", "explain": "'Espero que' attiva il congiuntivo presente; 'conseguir' per 'ele' è 'consiga' con il cambio ortografico.", "wrongNote": "'Espero que' chiede il congiuntivo presente nella forma di lui/lei: 'consiga'. Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).", "distractorNotes": {"consegue": "Il presente — ma questa frase richiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "conseguisse": "Il congiuntivo imperfetto — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "conseguirá": "Il futuro — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).)."}},
  "verbo-170": {"promptNative": "Appena io ___ (ver = vedere) il risultato, ti avviso.", "explain": "'Logo que' su un’azione futura regge il futuro del congiuntivo; 'ver' diventa l’irregolare 'vir', identico all’infinito di 'vir' — una trappola classica.", "wrongNote": "la congiunzione temporale di futuro chiede il congiuntivo futuro nella forma di io: 'vir'. Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.", "distractorNotes": {"ver": "L’infinito personale — ma questa frase richiede il futuro del congiuntivo (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.).", "verei": "Il futuro — ma questa frase chiede il congiuntivo futuro (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.).", "visse": "Il congiuntivo imperfetto — ma questa frase richiede il futuro del congiuntivo (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.)."}},
  "verbo-171": {"promptNative": "Lui ha parlato come se nulla ___ (haver = avere) successo.", "explain": "'Como se' con senso di trapassato richiede il congiuntivo imperfetto dell’ausiliare; 'haver' è 'houvesse'.", "wrongNote": "'Se' (se) chiede il congiuntivo imperfetto nella forma di lui/lei: 'houvesse'. Contesti di congiuntivo passato e l’ipotesi con 'se'.", "distractorNotes": {"houve": "Il passato prossimo — ma questa frase richiede il congiuntivo imperfetto (Contesti di congiuntivo al passato e l’ipotesi con 'se'.).", "havia": "L’imperfetto — ma questa frase richiede il congiuntivo imperfetto (Contesti di congiuntivo al passato e l’ipotesi con 'se'.).", "haja": "Il congiuntivo presente — ma questa frase chiede il congiuntivo imperfetto (Contesti di congiuntivo passato e l’ipotesi con 'se'.)."}},
  "verbo-172": {"promptNative": "Io dubito che ___ (trazer = portare) i documenti.", "explain": "'Duvido que' esprime dubbio e regge il congiuntivo presente; 'trazer' per 'eles' è l’irregolare 'tragam'.", "wrongNote": "'Duvido que' chiede il congiuntivo presente nella forma di loro: 'tragam'. Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).", "distractorNotes": {"trouxessem": "Il congiuntivo imperfetto — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "trazem": "Il presente — ma questa frase richiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "trarão": "Il futuro — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).)."}},
  "verbo-173": {"promptNative": "Quando noi ___ (dispor = disporre) di più risorse, ci espanderemo.", "explain": "'Quando' su una condizione futura regge il futuro del congiuntivo; 'dispor' (come 'pôr') per 'nós' è 'dispusermos'.", "wrongNote": "la congiunzione temporale di futuro chiede il congiuntivo futuro nella forma di noi: 'dispusermos'. Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.", "distractorNotes": {"dispuséssemos": "Il presente — ma questa frase richiede il futuro del congiuntivo (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.).", "disporemos": "Il presente — ma questa frase richiede il futuro del congiuntivo (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.).", "dispomos": "Il presente — ma questa frase richiede il futuro del congiuntivo (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.)."}},
  "verbo-174": {"promptNative": "Se tu ___ (satisfazer = soddisfare) i criteri, sarai approvato.", "explain": "'Se' pone una condizione futura reale che chiede il futuro del congiuntivo; 'satisfazer' (come 'fazer') per 'você' è 'satisfizer'.", "wrongNote": "'Se' (se) chiede il congiuntivo futuro nella forma di lui/lei: 'satisfizer'. Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.", "distractorNotes": {"satisfaz": "Il presente — ma questa frase richiede il futuro del congiuntivo (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.).", "satisfará": "Il futuro — ma questa frase chiede il congiuntivo futuro (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.).", "satisfizesse": "Il congiuntivo imperfetto — ma questa frase richiede il futuro del congiuntivo (Dopo 'quando' o 'se' riferito al futuro — un tempo tipico del portoghese.)."}},
  "verbo-175": {"promptNative": "Spero che loro ___ (chegar = arrivare) in tempo!", "explain": "'Oxalá' esprime un desiderio sul presente/futuro e regge il congiuntivo presente; 'chegar' per 'eles' è 'cheguem'.", "wrongNote": "'Oxalá' chiede il congiuntivo presente nella forma di loro: 'cheguem'. Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).", "distractorNotes": {"chegarão": "Il futuro — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "chegam": "Il presente — ma questa frase richiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "chegassem": "Il congiuntivo imperfetto — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).)."}},
  "verbo-176": {"promptNative": "Se noi ___ (reaver = recuperare) i soldi, sarebbe un sollievo.", "explain": "Un controfattuale con il condizionale 'ficaríamos' chiede il congiuntivo imperfetto; 'reaver' per 'nós' è 'reouvéssemos'.", "wrongNote": "'Se' (se) chiede il congiuntivo imperfetto nella forma di noi: 'reouvéssemos'. Contesti di congiuntivo passato e l’ipotesi con 'se'.", "distractorNotes": {"reaveríamos": "Il condizionale — ma questa frase richiede il congiuntivo imperfetto (Contesti di congiuntivo al passato e l’ipotesi con 'se'.).", "reavemos": "Il presente — ma questa frase chiede il congiuntivo imperfetto (Contesti di congiuntivo passato e l’ipotesi con 'se'.).", "reouvermos": "L’infinito personale — ma questa frase chiede il congiuntivo imperfetto (Contesti di congiuntivo passato e l’ipotesi con 'se'.)."}},
  "verbo-177": {"promptNative": "Purché tu ___ (manter = mantenere) la riservatezza, va bene.", "explain": "'Contanto que' ('con tal de que') regge il congiuntivo presente; 'manter' per 'vocês' è 'mantenham'.", "wrongNote": "la congiunzione di congiuntivo chiede il congiuntivo presente nella forma di loro: 'mantenham'. Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).", "distractorNotes": {"mantivessem": "Il congiuntivo imperfetto — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "mantêm": "Il presente — ma questa frase richiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).).", "manterão": "Il futuro — ma questa frase chiede il congiuntivo presente (Lo attivano il desiderio, il dubbio o l’emozione (espero que, talvez, embora).)."}},
